-- US: everything added after the albums / media migration (jar of reasons, open-when letters, time zones).
-- Generated by "npm run sql:bundle" from supabase/migrations. Safe to paste into the Supabase SQL editor.
-- Wrapped in a transaction: if anything fails, nothing is applied.

begin;

-- ===== 20260108000000_jar_openwhen_timezone.sql =====

-- Reasons jar, "open when…" letters, and each person's time zone.

-- 1) Time zone ------------------------------------------------------------------------------
alter table public.profiles add column timezone text check (timezone is null or timezone ~ '^[A-Za-z0-9_+/-]{1,64}$');

create function public.set_my_timezone(p_tz text) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  if p_tz is null or not exists (select 1 from pg_catalog.pg_timezone_names where name = p_tz) then
    raise exception 'invalid_timezone';
  end if;
  update public.profiles set timezone = p_tz where id = (select auth.uid()) and timezone is distinct from p_tz;
end;
$$;

-- 2) Jar of reasons ----------------------------------------------------------------------------
create table public.reasons (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  content         text not null check (char_length(btrim(content)) between 1 and 200),
  created_by      uuid not null references auth.users (id) on delete cascade,
  created_at      timestamptz not null default now()
);
create index reasons_space_idx on public.reasons (couple_space_id, created_at desc);
create trigger reasons_owner before insert on public.reasons for each row execute function public.set_shared_row_owner();
alter table public.reasons enable row level security;
create policy reasons_select on public.reasons for select to authenticated using (couple_space_id = (select public.my_space_id()));
create policy reasons_insert on public.reasons for insert to authenticated
  with check (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
create policy reasons_delete on public.reasons for delete to authenticated
  using (couple_space_id = (select public.my_space_id()) and created_by = (select auth.uid()));
grant select, delete on public.reasons to authenticated;
grant insert (content) on public.reasons to authenticated;

-- 3) "Open when…" letters ----------------------------------------------------------------------
-- The label and status are visible to both; the text stays locked for the recipient until they open it.
create table public.open_when_letters (
  id              uuid primary key default gen_random_uuid(),
  couple_space_id uuid not null references public.couple_spaces (id) on delete cascade,
  author_id       uuid not null references auth.users (id) on delete cascade,
  recipient_id    uuid not null references auth.users (id) on delete cascade,
  label           text not null check (char_length(btrim(label)) between 1 and 60),
  style           text not null default 'love_letter' check (style in ('love_letter', 'old_letter', 'little_note', 'heart_message', 'hug_in_words', 'secret_message')),
  created_at      timestamptz not null default now(),
  opened_at       timestamptz,
  check (author_id <> recipient_id)
);
create index open_when_space_idx on public.open_when_letters (couple_space_id, created_at desc);

create table public.open_when_bodies (
  letter_id uuid primary key references public.open_when_letters (id) on delete cascade,
  content   text not null check (char_length(btrim(content)) between 1 and 3000)
);

alter table public.open_when_letters enable row level security;
alter table public.open_when_bodies enable row level security;
create policy open_when_select on public.open_when_letters for select to authenticated
  using (couple_space_id = (select public.my_space_id()));
create policy open_when_body_select on public.open_when_bodies for select to authenticated
  using (exists (
    select 1 from public.open_when_letters l
    where l.id = letter_id
      and (l.author_id = (select auth.uid()) or (l.recipient_id = (select auth.uid()) and l.opened_at is not null))
  ));
grant select on public.open_when_letters, public.open_when_bodies to authenticated;

create function public.write_open_when(p_label text, p_content text, p_style text default 'love_letter') returns uuid
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid := public.my_space_id();
  rcpt uuid;
  new_id uuid;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  rcpt := public.partner_of(sp);
  if rcpt is null then raise exception 'no_active_space'; end if;
  if char_length(btrim(coalesce(p_label, ''))) not between 1 and 60
     or char_length(btrim(coalesce(p_content, ''))) not between 1 and 3000 then
    raise exception 'invalid_content';
  end if;
  if (select count(*) from public.open_when_letters where couple_space_id = sp) >= 100 then raise exception 'limit_reached'; end if;
  perform public.consume_rate_limit('open_when', 20, interval '1 hour');
  begin
    insert into public.open_when_letters (couple_space_id, author_id, recipient_id, label, style)
    values (sp, uid, rcpt, btrim(p_label), coalesce(p_style, 'love_letter'))
    returning id into new_id;
  exception when check_violation then
    raise exception 'invalid_content';
  end;
  insert into public.open_when_bodies (letter_id, content) values (new_id, btrim(p_content));
  return new_id;
end;
$$;

-- Only the recipient can open it, and opening is what unlocks the text for them.
create function public.open_open_when(p_id uuid) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  l public.open_when_letters;
  body text;
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  update public.open_when_letters set opened_at = coalesce(opened_at, now())
    where id = p_id and recipient_id = (select auth.uid())
    returning * into l;
  if not found then raise exception 'not_found'; end if;
  select content into body from public.open_when_bodies where letter_id = l.id;
  return jsonb_build_object('id', l.id, 'label', l.label, 'style', l.style, 'author_id', l.author_id, 'opened_at', l.opened_at, 'content', body);
end;
$$;

-- The author can still take a letter back as long as it has not been opened.
create function public.delete_open_when(p_id uuid) returns void
language plpgsql security definer set search_path = ''
as $$
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  delete from public.open_when_letters where id = p_id and author_id = (select auth.uid()) and opened_at is null;
  if not found then raise exception 'not_found'; end if;
end;
$$;

revoke all on function public.set_my_timezone(text), public.write_open_when(text, text, text), public.open_open_when(uuid), public.delete_open_when(uuid) from public, anon, authenticated;
grant execute on function public.set_my_timezone(text), public.write_open_when(text, text, text), public.open_open_when(uuid), public.delete_open_when(uuid) to authenticated;

-- ===== 20260109000000_hug_clothes.sql =====

-- Characters get clothes (top, scarf, hat) and a new gesture: the hug.
-- The hug is a wordless message of its own type, so it flows through the same push, privacy and read logic.

-- 1) New message type --------------------------------------------------------------
alter table public.messages drop constraint messages_message_type_check;
alter table public.messages add constraint messages_message_type_check check (message_type in (
  'love_letter', 'little_note', 'heart_message', 'hug_in_words', 'secret_message', 'old_letter',
  'quick', 'thinking_of_you', 'voice_note', 'drawing', 'hug'));

-- 2) send_message accepts 'hug' (100 chars max, no song, not schedulable, shares the "ping" limiter) --
drop function public.send_message(text, text, uuid, jsonb, jsonb, timestamptz);

create function public.send_message(
  p_content text, p_type text, p_client_id uuid,
  p_song jsonb default null, p_attachment jsonb default null, p_deliver_at timestamptz default null
) returns jsonb
language plpgsql security definer set search_path = ''
as $$
declare
  uid uuid := (select auth.uid());
  sp uuid;
  sp_status text;
  rcpt uuid;
  clean text := btrim(coalesce(p_content, ''));
  max_len integer;
  att_path text;
  att_secs integer;
  existing public.messages;
  created public.messages;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if p_client_id is null then raise exception 'invalid_content'; end if;

  max_len := case p_type
    when 'thinking_of_you' then 100
    when 'hug' then 100
    when 'little_note' then 280
    when 'voice_note' then 300
    when 'drawing' then 300
    when 'quick' then 500
    when 'heart_message' then 500
    when 'hug_in_words' then 1000
    when 'secret_message' then 1500
    when 'love_letter' then 3000
    when 'old_letter' then 3000
    else null end;
  if max_len is null then raise exception 'invalid_message_type'; end if;
  if clean = '' and p_type = 'voice_note' then clean := 'Voice note'; end if;
  if clean = '' and p_type = 'drawing' then clean := 'Drawing'; end if;
  if char_length(clean) = 0 or char_length(clean) > max_len then raise exception 'invalid_content'; end if;
  if p_song is not null and jsonb_typeof(p_song) <> 'object' then raise exception 'invalid_song'; end if;
  if p_type in ('thinking_of_you', 'hug', 'voice_note', 'drawing') and p_song is not null then raise exception 'invalid_song'; end if;

  sp := public.my_space_id();
  select status into sp_status from public.couple_spaces where id = sp;
  if sp is null or sp_status <> 'active' then raise exception 'no_active_space'; end if;
  rcpt := public.partner_of(sp);
  if rcpt is null then raise exception 'no_active_space'; end if;

  -- attachment: required for voice notes and drawings, forbidden otherwise
  if p_type in ('voice_note', 'drawing') then
    if p_attachment is null or jsonb_typeof(p_attachment) <> 'object' then raise exception 'invalid_attachment'; end if;
    att_path := p_attachment ->> 'path';
    begin
      att_secs := (p_attachment ->> 'seconds')::integer;
    exception when others then
      raise exception 'invalid_attachment';
    end;
    if att_path is null or position(sp::text || '/' in att_path) <> 1 then raise exception 'invalid_attachment'; end if;
    if not exists (select 1 from storage.objects where bucket_id = 'couple-media' and name = att_path) then
      raise exception 'invalid_attachment';
    end if;
  elsif p_attachment is not null then
    raise exception 'invalid_attachment';
  end if;

  if p_deliver_at is not null then
    if p_type in ('thinking_of_you', 'hug') or p_deliver_at < now() + interval '1 minute' or p_deliver_at > now() + interval '5 years' then
      raise exception 'invalid_schedule';
    end if;
  end if;

  select * into existing from public.messages where sender_id = uid and client_id = p_client_id;
  if found then
    return jsonb_build_object('message', to_jsonb(existing), 'is_new', false);
  end if;

  perform public.consume_rate_limit('message', 30, interval '10 minutes');
  if p_type in ('thinking_of_you', 'hug') then
    perform public.consume_rate_limit('ping', 10, interval '10 minutes');
  end if;

  begin
    insert into public.messages (
      couple_space_id, sender_id, recipient_id, content, message_type, client_id, deliver_at,
      attachment_path, attachment_seconds,
      song_track_id, song_title, song_artist, song_preview_url, song_artwork_url, song_start, song_duration
    ) values (
      sp, uid, rcpt, clean, p_type, p_client_id, p_deliver_at,
      att_path, att_secs,
      p_song ->> 'track_id', p_song ->> 'title', p_song ->> 'artist', p_song ->> 'preview_url', p_song ->> 'artwork_url',
      (p_song ->> 'start')::integer, (p_song ->> 'duration')::integer
    )
    returning * into created;
  exception
    when unique_violation then
      select * into existing from public.messages where sender_id = uid and client_id = p_client_id;
      return jsonb_build_object('message', to_jsonb(existing), 'is_new', false);
    when check_violation or invalid_text_representation or numeric_value_out_of_range then
      raise exception '%', case when p_song is not null then 'invalid_song' else 'invalid_attachment' end;
  end;
  return jsonb_build_object('message', to_jsonb(created), 'is_new', true);
end;
$$;

revoke all on function public.send_message(text, text, uuid, jsonb, jsonb, timestamptz) from public, anon, authenticated;
grant execute on function public.send_message(text, text, uuid, jsonb, jsonb, timestamptz) to authenticated;

-- 3) save_character allows the clothing keys ----------------------------------------
create or replace function public.save_character(p_config jsonb) returns void
language plpgsql security definer set search_path = ''
as $$
declare
  sp uuid := public.my_space_id();
  allowed text[] := array['head','hair','hairColor','skinColor','eyes','eyebrows','nose','mouth','glasses','beard',
                          'earrings','freckles','hairAccessories','backgroundColor','eyesColor','eyebrowsColor',
                          'glassesColor','mouthColor','top','topColor','scarf','scarfColor','hat','hatColor'];
  k text;
  v jsonb;
begin
  if (select auth.uid()) is null then raise exception 'not_authenticated'; end if;
  if sp is null or (select status from public.couple_spaces where id = sp) <> 'active' then raise exception 'no_active_space'; end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object' or octet_length(p_config::text) > 1200 then
    raise exception 'invalid_character';
  end if;
  for k, v in select * from jsonb_each(p_config) loop
    if not (k = any (allowed)) or jsonb_typeof(v) <> 'string' or (v #>> '{}') !~ '^[A-Za-z0-9]{1,16}$' then
      raise exception 'invalid_character';
    end if;
  end loop;
  perform public.consume_rate_limit('character', 60, interval '1 hour');
  insert into public.characters (couple_space_id, designer_id, config)
  values (sp, (select auth.uid()), p_config)
  on conflict (couple_space_id, designer_id) do update set config = excluded.config, updated_at = now();
end;
$$;

revoke all on function public.save_character(jsonb) from public, anon, authenticated;
grant execute on function public.save_character(jsonb) to authenticated;

-- ===== 20260110000000_photo_places.sql =====

-- Where a photo was taken, for the map in the albums. Optional, and only the two of you can see it.

alter table public.photos
  add column lat   double precision check (lat is null or lat between -90 and 90),
  add column lng   double precision check (lng is null or lng between -180 and 180),
  add column place text check (place is null or char_length(place) <= 120),
  add constraint photos_lat_lng_together check ((lat is null) = (lng is null));

grant insert (lat, lng, place) on public.photos to authenticated;
grant update (lat, lng, place) on public.photos to authenticated;

-- ===== 20260111000000_home_background.sql =====

-- A personal choice: use one of your couple's photos as the background of the home screen.
-- Only the person who chose it sees it as their background.

alter table public.user_preferences
  add column home_bg_path text check (home_bg_path is null or home_bg_path ~ '^[0-9a-f-]{36}/photos/[0-9a-f-]{36}\.(jpg|png|webp)$');

-- The photo has to belong to my own couple space and really exist.
create function public.verify_home_background() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if new.home_bg_path is not null and new.home_bg_path is distinct from old.home_bg_path then
    if position(coalesce(public.my_space_id()::text, '-') || '/' in new.home_bg_path) <> 1
       or not exists (select 1 from storage.objects where bucket_id = 'couple-media' and name = new.home_bg_path) then
      raise exception 'invalid_photo';
    end if;
  end if;
  return new;
end;
$$;
create trigger user_preferences_home_bg before update on public.user_preferences for each row execute function public.verify_home_background();

grant update (home_bg_path) on public.user_preferences to authenticated;

commit;
